    "intel": 80,
    "era": "gempei",
    "skill": "木曽源氏の誇り",
    "lore": "以仁王の令旨に応じて挙兵し、倶利伽羅峠で平氏を破って入京した。のち粟津で討たれた。",
    "birthYear": 1150,
    "deathYear": 1205,
    "isDaimyo": true
