    "politic": 74,
    "intel": 75,
    "era": "heian",
    "skill": "美濃源氏の旗頭",
    "lore": "美濃源氏の領袖。平治の乱で平家に属し美濃の支配を固めた。治承・寿永の乱でも美濃の軍勢を率いた。",
    "birthYear": 1135,
    "deathYear": 1184,
