    "clanId": "heian_court",
    "defaultProv": "tosa",
    "military": 72,
    "politic": 83,
    "intel": 80,
    "era": "ancient",
    "skill": "大納言の治定",
    "lore": "平安中期の公卿。大納言・治部卿。清廉潔白な人柄で知られ、地方受領の監察と南海道諸国の治安維持に心を砕いた。前九年の役に際しても国家の安寧を祈念し、朝廷秩序の維持に生涯を捧げた名臣。",
    "birthYear": 1005,
    "deathYear": 1060,
