    "politic": 82,
    "intel": 86,
    "era": "ancient",
    "skill": "大江山鬼退治",
    "lore": "満仲の長男。大江山の酒呑童子や土蜘蛛を討ち取った伝説の猛将。道長の側近として朝廷の莫大な利権管理にも食い込んだ。",
    "birthYear": 948,
    "deathYear": 1021,
