    "lore": "河内源氏。平治の乱の後伊豆に流され、治承4年（1180年）に以仁王の令旨に応じて挙兵した。富士川の戦いで平氏を退け、鎌倉を本拠に侍所・公文所・問注所を置いて武家政権の形を作った。建久3年（1192年）に征夷大将軍となり、正治元年（1199年）に没した。",
