    "lore": "松平氏から徳川を称した三河の大名。桶狭間の後に織田と結び、本能寺の変の後は関東へ移って江戸を本拠とした。慶長5年（1600年）の関ヶ原で西軍を破り、同8年に征夷大将軍となって江戸幕府を開いた。元和2年（1616年）、大坂の陣で豊臣氏を滅ぼした直後に没した。",
